                _check_value(idx, value, min_val, max_val)
            else:
                # If a bare value is provided, we cannot determine bounds;
                # skip or raise an informative error.
                raise TypeError(
                    f"Item at index {idx} is not a 3‑tuple (value, min, max)"
                )
    return args

